def process(known_causes) -> pd.DataFrame:
    df = known_causes.copy()
    contingency = pd.crosstab(df['region'], df['cause'])
    return contingency.reset_index()

def process(cause_by_region) -> pd.DataFrame:
    from scipy.stats import chi2_contingency

    contingency_table = cause_by_region.set_index('region')[['H', 'L', 'N']].values
    chi2, p_value, dof, expected = chi2_contingency(contingency_table)

    result = pd.DataFrame({
        'chi_square_statistic': [chi2],
        'p_value': [p_value]
    })

    return result
